/* Presentation for confirmed field reports. All state changes remain on the local server. */
(()=>{
  'use strict';
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const stageNames={ack:'收到任务',contact:'已联系',board:'已接到上车',arrive:'已到达待核验',report:'异常反馈'};
  const kindNames={road:'道路受阻',people:'新增人员',medical:'医疗协助',hazard:'险情变化',progress:'任务进展',other:'其他反馈'};
  const sourceNames={voice:'语音整理',text:'文字整理',quick:'快捷操作',manual:'手动填写'};
  const householdStage={superseded:'已更正归档',waiting:'待接送',boarded:'已上车',arrived:'到达待核验',verified:'已人工核验'};
  const clock=x=>x?new Date(x).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
  const nodeName=(d,id)=>d.scenario.nodes.find(n=>n.id===id)?.label||id||'—';
  const placeName=(d,id)=>id==='east'?'演练东桥':id==='north'?'演练北桥':d.scenario.edges.some(e=>e.id===id)?(()=>{const e=d.scenario.edges.find(e=>e.id===id);return nodeName(d,e.from)+'—'+nodeName(d,e.to);})():nodeName(d,id);
  function tasks(state,ui,h){
    const d=state.data,v=d.scenario.vehicles.find(v=>v.id===ui.vehicleId),p=d.activePlan,r=p?.routes.find(r=>r.vehicleId===ui.vehicleId),f=d.fleet[ui.vehicleId];
    const ack=!!(p&&d.taskAcks?.[ui.vehicleId]?.planId===p.id),blocked=state.blockedVehicles.includes(ui.vehicleId),stops=r?.stops||[];
    const contact=stops.find(st=>d.stage[st.id]==='waiting'&&!d.contacts[st.id]?.contacted),next=stops.find(st=>d.stage[st.id]==='waiting');
    const operational=!!(p&&r?.people&&!f?.finished);
    return `<section class="panel field-task-panel" id="field-tasks">${h.head('① 现场执行任务','选择负责的车辆，按现场事实登记；快捷操作也需确认',h.badge(p?p.id:'等待发布',p?'teal':'gray'))}<div class="panel-body"><label for="field-vehicle">当前执行车辆</label><select id="field-vehicle" ${ui.voiceState.active?'disabled':''}><option value="">请选择负责的演练车辆</option>${d.scenario.vehicles.map(x=>`<option value="${x.id}" ${ui.vehicleId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${!v?'<p class="empty">先选择车辆，可查看对应家庭、下一环节与指挥台安排。</p>':!p?'<div class="notice">指挥台尚未发布任务。可先上报现场异常，收到方案后再确认接收。</div>':`<div class="field-task-meta"><strong>${esc(v.name)} · ${esc(nodeName(d,f.node))}</strong>${h.badge(f.finished?'本趟已到达':ack?'当前方案已接收':'请确认收到任务',ack?'teal':'gray')}</div><p class="boundary">${d.phase==='preparation'?'出发前：先接收任务并逐户联系，由指挥台启动模拟执行。':'模拟执行中：依次登记接人，到达后等待指挥台核验。'} ${blocked?'路线或人员批次已变化，请等待重新规划并确认。':''}</p><div class="actions">${h.btn('确认收到任务','field-quick',`data-stage="ack" ${!operational||ack?'disabled':''}`,ack?'quiet':'primary')}${h.btn('登记到达安置点','field-quick',`data-stage="arrive" ${!operational||!ack||d.phase!=='executing'||next||!f.onboard.length||blocked?'disabled':''}`)}</div><div class="field-households">${stops.length?stops.map(st=>{const item=d.scenario.households.find(x=>x.id===st.id);return `<article><div><strong>${esc(item?.name||st.id)} · ${st.people} 人</strong><small>${esc(householdStage[d.stage[st.id]])} · ${d.contacts[st.id]?.contacted?'已联系':'待联系'}</small></div><div class="actions">${h.btn('登记已联系','field-quick',`data-stage="contact" data-household="${st.id}" ${!operational||!ack||contact?.id!==st.id?'disabled':''}`,'small')}${h.btn('登记已接到','field-quick',`data-stage="board" data-household="${st.id}" ${!operational||!ack||d.phase!=='executing'||next?.id!==st.id||!d.contacts[st.id]?.contacted||blocked?'disabled':''}`,'small')}</div></article>`;}).join(''):'<p class="empty">该车辆当前没有接送家庭任务。</p>'}</div>${r?.shelterId?`<p class="boundary">发布方案目的地：${esc(d.scenario.shelters.find(x=>x.id===r.shelterId)?.name)}。车辆位置为人工登记节点。</p>`:''}`}</div></section>`;
  }
  function assistant(state,ui,h){
    const d=state.data,r=d.activePlan?.routes.find(r=>r.vehicleId===ui.vehicleId),v=ui.voiceState;
    return `<section class="panel assistant-panel field-agent-panel" id="field-agent"><div class="assistant-heading"><span class="ai-emblem" aria-hidden="true">声</span><div><span class="eyebrow">说清现场 · 确认后同步</span><h2>② 语音协同助手</h2></div>${h.badge('浏览器识别','teal')}</div><div class="panel-body"><div class="field-scene-grid">${[['road','道路受阻','路'],['people','新增人员','人'],['medical','医疗协助','援'],['hazard','险情变化','险']].map(([id,label,mark])=>h.btn(`<b aria-hidden="true">${mark}</b><span>${label}</span>`,'field-scene',`data-id="${id}"`,'scene-button')).join('')}</div><p class="boundary">任务进展可用上方快捷按钮；异常可语音说明，也可点击场景后手动填写。</p><div class="form-grid field-context"><div><label for="field-household">涉及家庭（可选）</label><select id="field-household" ${v.active?'disabled':''}><option value="">由语音明确，或在此选择</option>${(r?.stops||[]).map(st=>`<option value="${st.id}" ${ui.householdId===st.id?'selected':''}>${esc(d.scenario.households.find(x=>x.id===st.id)?.name||st.id)}</option>`).join('')}</select></div><div><label for="field-location">现场位置（可选）</label><select id="field-location" ${v.active?'disabled':''}><option value="">由语音明确，或在此选择</option><optgroup label="演练路段">${d.scenario.edges.map(e=>`<option value="${e.id}" ${ui.location===e.id?'selected':''}>${esc(placeName(d,e.id))}</option>`).join('')}</optgroup><optgroup label="演练点位">${d.scenario.nodes.map(n=>`<option value="${n.id}" ${ui.location===n.id?'selected':''}>${esc(n.label)}</option>`).join('')}</optgroup></select></div></div><div class="field-voice-composer"><label for="field-utterance">说出或输入现场情况</label><textarea id="field-utterance" maxlength="2000" ${v.active?'readonly':''} placeholder="例如：演练东桥有倒树，车辆无法通行。\n或：演练家庭 02 已联系。">${esc(ui.utterance)}</textarea>${h.voiceHTML('field-agent')}<div class="actions">${h.btn('整理为待确认内容','field-prepare',v.active?'disabled':'','primary')}${h.btn('清空草稿','field-clear',v.active?'disabled':'','quiet')}</div></div><p class="assistant-mode">语音由浏览器服务识别，可能联网；本地规则整理任务和字段，未接入大模型。识别结果不会自动提交，听不清或信息缺失时会请您补充。</p></div></section>`;
  }
  function preview(state,ui,h){
    const d=state.data,p=ui.prepared,proposal=p?.proposal,payload=proposal?.payload,stale=p&&(p.session!==state.session||p.revision!==d.revision);
    let body='';
    if(!p)body='<div class="field-preview-empty"><span aria-hidden="true">✓</span><strong>确认前，先看清将提交什么</strong><p>点击任务快捷按钮，或说完后结束识别。整理好的内容会出现在这里。</p></div>';
    else{
      body=`<h3>${esc(p.title||'待确认内容')}</h3><p>${esc(p.summary)}</p>${p.questions?.length?`<div class="notice warn"><strong>还需要补充</strong>${p.questions.map(x=>`<p>${esc(x)}</p>`).join('')}<p>请在左侧选择家庭或位置，或补充描述后重新整理。</p></div>`:''}`;
      if(payload){const vehicle=d.scenario.vehicles.find(x=>x.id===payload.vehicleId),house=d.scenario.households.find(x=>x.id===payload.householdId);const rows=proposal.action==='field-progress'?[['操作',stageNames[payload.stage]],['车辆',vehicle?.name],['任务方案',payload.planId],['涉及家庭',house?house.name+' · '+house.people+' 人':null],['随车人数',payload.stage==='arrive'?(d.fleet[payload.vehicleId]?.onboard||[]).reduce((n,id)=>n+(d.scenario.households.find(x=>x.id===id)?.people||0),0)+' 人':null],['到达安置点',payload.stage==='arrive'?d.scenario.shelters.find(x=>x.id===d.activePlan?.routes.find(r=>r.vehicleId===payload.vehicleId)?.shelterId)?.name:null]]:[['反馈类型',kindNames[payload.kind]],['关联位置',placeName(d,payload.location)],['新增人数',payload.kind==='people'?payload.people+' 人':null],['协助需求',payload.kind==='people'?[payload.wheelchair?'需要轮椅位':'',payload.assistance?'需要协助':''].filter(Boolean).join('、')||'未声明':null]];
        body+=`<dl class="proposal-facts">${rows.filter(x=>x[1]!==null&&x[1]!==undefined).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>内容来源</dt><dd>${esc(sourceNames[payload.source]||'人工整理')}</dd></div></dl>${payload.text?`<blockquote class="field-original">${esc(payload.text)}</blockquote>`:''}`;
      }
      if(p.warnings?.length)body+=`<p class="boundary">${p.warnings.map(esc).join('；')}</p>`;
      if(p.evidence?.length)body+=`<details class="field-evidence"><summary>查看整理依据</summary>${p.evidence.map(x=>`<p>${esc(typeof x==='string'?x:JSON.stringify(x))}</p>`).join('')}</details>`;
      if(stale)body+='<div class="notice warn">演练已更新，这份待确认内容已过期。请重新选择任务或整理描述后再确认。</div>';
      if(proposal)body+=`<form id="field-confirm-form"><label for="field-reporter">本次上报人</label><input id="field-reporter" maxlength="40" value="${esc(ui.reporter)}" required><label class="check"><input id="field-confirm-check" type="checkbox" required ${ui.confirmed?'checked':''}>我已核对位置、对象和事实，确认提交这条演练记录。</label><button class="primary field-confirm-button" type="submit" ${stale||ui.busy||ui.voiceState.active||!ui.connected?'disabled':''}>确认并同步到指挥台 ↗</button></form>`;
    }
    return `<section class="panel field-preview-panel" id="field-preview">${h.head('③ 核对并同步','只同步您确认提交的内容',h.badge(proposal?'待确认':'等待输入',proposal?'teal':'gray'))}<div class="panel-body">${body}</div></section>${ui.receipt?`<div class="notice field-receipt" role="status"><strong>✓ ${esc(ui.receipt.title)}</strong><p>${esc(ui.receipt.detail)}</p><small>${clock(ui.receipt.time)} · ${window.JiaoyingPages?'已保存到此浏览器，并通知同浏览器网页。':'服务已接收，已推送在线网页。'}</small><p><a href="./#command" target="_blank" rel="noopener">打开指挥台查看 ↗</a></p></div>`:''}`;
  }
  function live(state,ui,h){
    const d=state.data,events=d.fieldEvents||[],visible=ui.allEvents?events:events.slice(0,4),status={pending:'待核实',accepted:'已采纳',rejected:'未采纳',coordination:'待协调',resolved:'已处理'};
    const last=events[0];
    const chips=[['接收任务',Object.values(d.taskAcks||{}).filter(x=>x.planId===d.activePlan?.id).length+' 车'],['联系家庭',Object.values(d.contacts).filter(x=>x.contacted).length+' 户'],['已上车',state.metrics.boarded+' 人'],['到达待核验',state.metrics.arrived+' 人'],['异常待核实',state.metrics.pendingReports+' 条']];
    return `<section class="panel field-live-panel" id="field-live">${h.head('现场协同实况','与现场网页共享任务、反馈和处理结果',h.badge(ui.live?(state.capabilities?.browserOnly?'同浏览器同步已连接':'即时推送已连接'):ui.connected?'轮询同步中':'连接中断',ui.connected?'teal':'red'))}<div class="field-stage-strip">${chips.map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><div class="field-live-events" role="log" aria-label="现场确认记录">${visible.length?visible.map(e=>{const r=e.villageReportId?d.villageReports?.find(x=>x.id===e.villageReportId):e.reportId?d.reports.find(x=>x.id===e.reportId):null;return `<article class="field-live-event"><span class="event-symbol" aria-hidden="true">${e.kind==='village'?'村':e.kind==='report'?'!':'✓'}</span><div><div class="close-row"><strong>${esc(e.summary||stageNames[e.stage]||'现场确认记录')}</strong>${h.badge(r?status[r.status]||r.status:e.stage==='arrive'?'待人工核验':'已登记',r?.status==='pending'?'red':'teal')}</div><p>${esc(e.text||'已按快捷环节人工确认。')}</p><small>${clock(e.time)} · ${esc(e.reporter)} · ${esc(sourceNames[e.source]||'现场提交')}${e.planId?' · '+esc(e.planId):''}</small></div>${h.btn(['village','report'].includes(e.kind)?'查看处理':'查看进展','field-event',`data-id="${e.id}"`,'small quiet')}</article>`;}).join(''):'<div class="empty">等待现场确认。现场端可接收任务、登记联系、上车、到达，也可上报道路受阻或新增人员。提交后会即时显示在这里。</div>'}</div>${events.length>4?`<div class="panel-body">${h.btn(ui.allEvents?'收起较早记录':'查看全部现场记录','field-events-toggle','','small quiet')}</div>`:''}<div class="field-sync-note"><span class="live-dot ${ui.live?'is-live':''}"></span>${last?'最近现场确认 '+clock(last.time):'双方无需手动刷新'} · 到达登记与人工核验分开处理</div></section>`;
  }
  window.JiaoyingFieldUI={tasks,assistant,preview,live,stageNames,sourceNames};
})();
